use lat_protocol::{EntityId, Event, Relationship, SocialEvent, RelationshipType};
use std::collections::HashMap;

pub struct SocialEngine {
    rels: HashMap<(EntityId, EntityId), f32>,
}

impl SocialEngine {
    pub fn new() -> Self {
        Self {
            rels: HashMap::new(),
        }
    }

    pub fn add_relationship(&mut self, rel: Relationship) {
        let key = Self::canonical_key(rel.a, rel.b);
        self.rels.insert(key, rel.strength);
    }

    pub fn get_strength(&self, a: EntityId, b: EntityId) -> f32 {
        let key = Self::canonical_key(a, b);
        *self.rels.get(&key).unwrap_or(&0.0)
    }

    pub fn current_relationships(&self) -> Vec<Relationship> {
        self.rels.iter().map(|((a, b), strength)| Relationship {
            a: *a,
            b: *b,
            rel_type: RelationshipType::Friendship,
            strength: *strength,
        }).collect()
    }

    /// Decay all relationships by x0.99 per tick.
    pub fn tick(&mut self) -> Vec<Event> {
        let mut events = Vec::new();
        for ((a, b), strength) in self.rels.iter_mut() {
            *strength *= 0.99;
            events.push(Event::Social(SocialEvent::RelationshipDecayed {
                a: *a,
                b: *b,
                new_strength: *strength,
            }));
        }
        events
    }

    fn canonical_key(a: EntityId, b: EntityId) -> (EntityId, EntityId) {
        if a.0 <= b.0 { (a, b) } else { (b, a) }
    }
}
