pub mod snapshot;

use lat_protocol::{Event, SystemEvent};
use lat_dungeon::DungeonEngine;
use lat_economy::Economy;
use lat_social::SocialEngine;
use lat_life::LifeEngine;
use lat_memory::KnowledgeNetwork;
use lat_ceo::CeoEngine;
use lat_world::World;
use snapshot::Snapshot;

pub struct Engine {
    dungeon: DungeonEngine,
    economy: Economy,
    social: SocialEngine,
    life: LifeEngine,
    memory: KnowledgeNetwork,
    ceo: CeoEngine,
    world: World,
}

impl Engine {
    pub fn new() -> Self {
        Self {
            dungeon: DungeonEngine::new(),
            economy: Economy::new(0),
            social: SocialEngine::new(),
            life: LifeEngine::new(),
            memory: KnowledgeNetwork::new(),
            ceo: CeoEngine::new(),
            world: World::new(),
        }
    }

    /// Build immutable snapshot (value copy, no references).
    pub fn build_snapshot(&self) -> Snapshot {
        Snapshot {
            facilities: self.world.facilities.clone(),
            treasury: self.economy.treasury,
            relationships: self.social.current_relationships(),
            memory_graph: HashMap::new(),
        }
    }

    /// Core tick flow (spec-aligned):
    /// 1. Snapshot Build (immutable)
    /// 2. Subsystem Tick (pure functions)
    /// 3. Event Collection
    /// 4. CEO Decision
    /// 5. State Update (engine only)
    /// 6. Resonance Update
    /// 7. TickCompleted
    pub fn tick(&mut self) -> Vec<Event> {
        // 1. Build immutable snapshot
        let _snapshot = self.build_snapshot();

        // 2-3. Run subsystems and collect events
        let mut events: Vec<Event> = Vec::new();

        events.extend(self.dungeon.tick());
        events.extend(self.life.tick());
        events.extend(self.social.tick());

        // 4. CEO Decision
        let ceo_events = self.ceo.tick(self.economy.treasury);
        events.extend(ceo_events);

        // 5. State Update (engine only - apply dungeon rewards to economy)
        for event in &events {
            if let Event::Dungeon(lat_protocol::DungeonEvent::JobCompleted { reward_money, .. }) = event {
                self.economy.apply_dungeon_reward(*reward_money);
            }
        }

        // 6. Economy tick (emits treasury update)
        events.extend(self.economy.tick());

        // 7. TickCompleted marker
        events.push(Event::System(SystemEvent::TickCompleted));

        events
    }
}
