```rust
use lat_protocol::{EntityId, MemoryShard};
use std::collections::HashMap;
use uuid::Uuid;

pub struct KnowledgeNetwork { store: HashMap<EntityId, Vec<MemoryShard>> }

impl KnowledgeNetwork {
    pub fn new() -> Self { Self { store: HashMap::new() } }

    pub fn store(&mut self, owner: EntityId, shard: MemoryShard) {
        self.store.entry(owner).or_default().push(shard);
    }

    pub fn transfer(&mut self, from: EntityId, to: EntityId, shard_id: &Uuid, quality: f32) {
        if let Some(shards) = self.store.get_mut(&from) {
            if let Some(pos) = shards.iter().position(|s| s.id == *shard_id) {
                let mut shard = shards.remove(pos);
                shard.value = (shard.value as f32 * quality) as u32;
                shard.owner = to;
                self.store.entry(to).or_default().push(shard);
            }
        }
    }

    pub fn get(&self, owner: EntityId) -> Vec<MemoryShard> {
        self.store.get(&owner).cloned().unwrap_or_default()
    }
}
```

