```rust
use lat_protocol::{AgentId, EntityId, Event, LifeEvent, LifeStage};
use std::collections::HashMap;
use uuid::Uuid;

pub struct LifeEngine { agents: HashMap<AgentId, LifeStage> }

impl LifeEngine {
    pub fn new() -> Self { Self { agents: HashMap::new() } }
    pub fn register_agent(&mut self, id: AgentId, stage: LifeStage) { self.agents.insert(id, stage); }

    pub fn tick(&mut self) -> Vec<Event> {
        let mut events = Vec::new();
        let mut archived = Vec::new();
        for (id, stage) in self.agents.iter_mut() {
            let next = Self::next_stage(*stage);
            if next != *stage {
                events.push(Event::Life(LifeEvent::LifeStageChanged { agent_id: *id, from: *stage, to: next }));
                *stage = next;
            }
            if *stage == LifeStage::Archived { archived.push(*id); }
        }
        for _ in archived {
            events.push(Event::Life(LifeEvent::LegacyNodeCreated { node_id: EntityId(Uuid::new_v4()) }));
        }
        events
    }

    fn next_stage(stage: LifeStage) -> LifeStage {
        match stage {
            LifeStage::Kindergarten => LifeStage::School,
            LifeStage::School => LifeStage::University,
            LifeStage::University => LifeStage::Junior,
            LifeStage::Junior => LifeStage::Worker,
            LifeStage::Worker => LifeStage::Senior,
            LifeStage::Senior => LifeStage::Mentor,
            LifeStage::Mentor => LifeStage::Retired,
            LifeStage::Retired => LifeStage::Archived,
            LifeStage::Archived | LifeStage::LegacyNode => stage,
        }
    }
}
