use actix_web::{get, web, App, HttpResponse, HttpServer, Responder};
use actix_web::http::header;
use clap::Parser;
use lat_engine::Engine;
use lat_protocol::Event;
use std::sync::Arc;
use tokio::sync::broadcast;

#[derive(Parser, Debug)]
#[command(author, version, about = "LAT server")]
struct Args {
    #[arg(long, env = "LAT_SERVER_PORT")]
    port: Option<u16>,
}

#[get("/health")]
async fn health() -> impl Responder { HttpResponse::Ok().body("OK") }

#[get("/state")]
async fn state(engine: web::Data<Arc<tokio::sync::Mutex<Engine>>>) -> impl Responder {
    let eng = engine.lock().await;
    let snap = eng.build_snapshot();
    HttpResponse::Ok().json(serde_json::json!({ "facilities": snap.facilities.len(), "treasury": snap.treasury }))
}

#[get("/events")]
async fn sse(tx: web::Data<broadcast::Sender<Event>>) -> impl Responder {
    let mut rx = tx.subscribe();
    let stream = async_stream::stream! {
        while let Ok(evt) = rx.recv().await {
            let json = serde_json::to_string(&evt).unwrap();
            yield Ok::<_, actix_web::Error>(web::Bytes::from(format!("data: {}\n\n", json)));
        }
    };
    HttpResponse::Ok().insert_header((header::CONTENT_TYPE, "text/event-stream")).streaming(stream)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let args = Args::parse();
    let port = args.port.unwrap_or_else(|| { eprintln!("Kein Port angegeben."); std::process::exit(1); });

    let engine = Arc::new(tokio::sync::Mutex::new(Engine::new()));
    let (tx, _rx) = broadcast::channel::<Event>(1024);
    let tx_data = web::Data::new(tx.clone());

    let eng_clone = engine.clone();
    let tx_clone = tx.clone();
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(tokio::time::Duration::from_secs(1));
        loop {
            interval.tick().await;
            let events = { eng_clone.lock().await.tick() };
            for ev in events { let _ = tx_clone.send(ev); }
        }
    });

    println!("LAT Server startet auf 0.0.0.0:{}", port);
    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(engine.clone()))
            .app_data(tx_data.clone())
            .service(health).service(state).service(sse)
    })
    .bind(("0.0.0.0", port))?.run().await
}
